import{_ as n,H as a,f as p,i as l}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"11｜老项目的 Skill 怎么挖？把重复流程变成可复用的技能","description":"","frontmatter":{},"headers":[{"level":2,"title":"老项目的 SKILL 的一些特点","slug":"老项目的-skill-的一些特点","link":"#老项目的-skill-的一些特点","children":[{"level":3,"title":"老项目特别需要 SKILL","slug":"老项目特别需要-skill","link":"#老项目特别需要-skill","children":[]},{"level":3,"title":"SKILL 的起点是“挖”，不是“设计”","slug":"skill-的起点是-挖-不是-设计","link":"#skill-的起点是-挖-不是-设计","children":[]},{"level":3,"title":"老项目里哪些流程值得挖","slug":"老项目里哪些流程值得挖","link":"#老项目里哪些流程值得挖","children":[]},{"level":3,"title":"一个老项目到底需要多少个 SKILL","slug":"一个老项目到底需要多少个-skill","link":"#一个老项目到底需要多少个-skill","children":[]}]},{"level":2,"title":"实操开始：让 AI 帮你挖","slug":"实操开始-让-ai-帮你挖","link":"#实操开始-让-ai-帮你挖","children":[{"level":3,"title":"第一步：让 AI 分析项目重复流程","slug":"第一步-让-ai-分析项目重复流程","link":"#第一步-让-ai-分析项目重复流程","children":[]},{"level":3,"title":"第二步：让 AI 出 Top 3 推荐","slug":"第二步-让-ai-出-top-3-推荐","link":"#第二步-让-ai-出-top-3-推荐","children":[]},{"level":3,"title":"第三步： 让 AI 生成完整的 CRUD SKILL","slug":"第三步-让-ai-生成完整的-crud-skill","link":"#第三步-让-ai-生成完整的-crud-skill","children":[]},{"level":3,"title":"第四步：生成技术文档自动更新的 SKILL","slug":"第四步-生成技术文档自动更新的-skill","link":"#第四步-生成技术文档自动更新的-skill","children":[]},{"level":3,"title":"第五步：测试 SKILL 真的能被触发","slug":"第五步-测试-skill-真的能被触发","link":"#第五步-测试-skill-真的能被触发","children":[]}]},{"level":2,"title":"几个注意点","slug":"几个注意点","link":"#几个注意点","children":[{"level":3,"title":"CLAUDE.md 和 SKILL 的分工","slug":"claude-md-和-skill-的分工","link":"#claude-md-和-skill-的分工","children":[]},{"level":3,"title":"60 分起步，养到 90 分","slug":"_60-分起步-养到-90-分","link":"#_60-分起步-养到-90-分","children":[]},{"level":3,"title":"不要堆工具，要在场景里用工具","slug":"不要堆工具-要在场景里用工具","link":"#不要堆工具-要在场景里用工具","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/11｜老项目的Skill怎么挖？把重复流程变成可复用的技能.md","filePath":"ClaudeCode企业级老项目改造实战/11｜老项目的Skill怎么挖？把重复流程变成可复用的技能.md","lastUpdated":1779815445000}'),e={name:"ClaudeCode企业级老项目改造实战/11｜老项目的Skill怎么挖？把重复流程变成可复用的技能.md"};function i(t,s,c,o,d,r){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="_11-老项目的-skill-怎么挖-把重复流程变成可复用的技能" tabindex="-1">11｜老项目的 Skill 怎么挖？把重复流程变成可复用的技能 <a class="header-anchor" href="#_11-老项目的-skill-怎么挖-把重复流程变成可复用的技能" aria-label="Permalink to &quot;11｜老项目的 Skill 怎么挖？把重复流程变成可复用的技能&quot;">​</a></h1><p>你好，我是 Robert。</p><p>上一讲结尾我留了一句话：还有一类东西没落地，就是反复要做的操作流程。这类东西放不进 CLAUDE.md，因为它不是常识、是操作。改造前的体检、PR 前的检查、文档跟着代码走， <strong>这些每次改造都要走一遍的流程，应该住到另一个地方，这个地方就是 SKILL</strong>。</p><p>07 讲里我们装过一个别人写的 SKILL（画图），那是消费者视角。这一讲换角度，教你 <strong>从自己的老项目里挖出重复流程，写成第一个可用的 SKILL</strong>，这是生产者视角。</p><p>学完这一讲，你会在项目的 <code>.claude/skills/</code> 目录里多一个实际能用的 SKILL。项目的 AI 协作基础设施从“别人给的”变成了“你自己养的”。</p><h2 id="老项目的-skill-的一些特点" tabindex="-1">老项目的 SKILL 的一些特点 <a class="header-anchor" href="#老项目的-skill-的一些特点" aria-label="Permalink to &quot;老项目的 SKILL 的一些特点&quot;">​</a></h2><h3 id="老项目特别需要-skill" tabindex="-1">老项目特别需要 SKILL <a class="header-anchor" href="#老项目特别需要-skill" aria-label="Permalink to &quot;老项目特别需要 SKILL&quot;">​</a></h3><p>先说为什么老项目和 SKILL 是天作之合。新项目你自己起的，每件事第一次做你都印象深，写不写 SKILL 差别不大。</p><p>老项目不一样，老项目的特征是“很多事情你反复做了很多次，但每次都凭记忆”。改造前体检、PR 前检查、文档同步、新增接口前对齐，这些事你每周都做，但因为没沉淀，每次都得重新想一遍流程。漏一步、错一步是常态。</p><p>更扎心的是： <strong>这些流程不只是你一个人在做，团队里每个人都在做，每个人做的细节还不一样</strong>。A 提 PR 前会跑测试和格式化，B 会顺手 review changelog，Robert 总是先做一次资产校对。三个人的 PR 过 review 的速度差三倍，原因不是能力差，是流程没标准化。</p><p>SKILL 的价值就在这里： <strong>把这些反复做但没沉淀的流程，固化成一个 AI 能自动执行的资产</strong>。A 装上之后，提 PR 前 AI 自动跑一遍 Robert 的全套流程；B 装上之后，AI 自动同步文档不会忘。 <strong>整个团队的下限被拉到上限</strong>。</p><p>老项目恰恰是 SKILL 的富矿，因为这种“反复做但没沉淀”的流程多到挖不完。等你挖完，你后面的开发就非常顺畅了。</p><h3 id="skill-的起点是-挖-不是-设计" tabindex="-1">SKILL 的起点是“挖”，不是“设计” <a class="header-anchor" href="#skill-的起点是-挖-不是-设计" aria-label="Permalink to &quot;SKILL 的起点是“挖”，不是“设计”&quot;">​</a></h3><p>讲挖之前先说清一件事，很多人开始写 SKILL 时第一反应是研究 YAML 格式、 <code>description</code> 怎么写、 <code>allowed-tools</code> 有哪些，这些都是有用的知识，但它们应该在挖到具体场景之后才学。</p><p><strong>SKILL 的起点是识别“我反复在做某件事”</strong>。没有重复流程就硬写 SKILL，产出的是一堆没人用的代码。Claude Code 扫 <code>~/.claude/skills/</code> 时每个 SKILL 都会被索引，不是性能问题，是 <strong>SKILL 写多了 AI 在多个 SKILL 之间会判断混乱、互相冲突</strong>。所以写之前先想清楚：这件事我是不是真的在反复做。</p><p>怎么判断一件事值不值得写成 SKILL？三个特征判断法：</p><ol><li><p><strong>可复制</strong>。同样的动作序列会被反复执行。不是“偶尔做一次”，是“这个月已经做了五次”。</p></li><li><p><strong>可参数化</strong>。只有几个变量在变，骨架是同一个。比如“新增一个接口”的流程：具体接口名不一样、入参出参不一样，但流程是一样的（先看 docs/api-list.md 里现有接口的路径规范、再看 data-model.md 里相关实体、再写实现、再补测试、再回头更新接口清单）。</p></li><li><p><strong>可自动化</strong>。动作序列有明确的起点和终点。起点：触发信号清晰；终点：产出物明确。不是那种“改着改着凭感觉做完了”的事。</p></li></ol><p><strong>三个特征同时满足，才值得写成 SKILL</strong>。差一个都别硬写。偶尔做的事写进文档就好，流程太发散的事留在脑子里就好，做成 SKILL 反而会把 AI 卡在错误的框里。</p><h3 id="老项目里哪些流程值得挖" tabindex="-1">老项目里哪些流程值得挖 <a class="header-anchor" href="#老项目里哪些流程值得挖" aria-label="Permalink to &quot;老项目里哪些流程值得挖&quot;">​</a></h3><p>老项目里有四类流程几乎家家都有，挖出来就能用：</p><ol><li><p><strong>技术文档自动更新</strong>。docs/ 里的接口清单、数据模型、架构图，代码每次改动都让其中某一份漂移。如果不主动同步，三份资产慢慢就和真实代码对不上了，半年后整个 docs/ 没人敢相信，最后变成“代码即文档”。这是老项目最常见的痛点： <strong>文档腐烂</strong>。一个 SKILL 把这件事自动化掉，团队再也不用花人力维护文档。</p></li><li><p><strong>改造前体检</strong>。动手改代码前至少要确认：当前测试是不是绿的、编译是不是通过、依赖的中间件是不是连得上。每次改造前都要跑一次。</p></li><li><p><strong>PR 前检查</strong>。提 PR 前的固定 checklist：测试跑过、格式化过、changelog 更新了、相关文档改了、找谁 review。团队有明确 checklist 的项目，这件事零变化地反复执行。</p></li><li><p><strong>新增接口前对齐</strong>。加一个新接口前，先看现有接口的路径风格、统一响应格式、错误码规则。对齐完再写，不然每个人加出来的接口各自为政。</p></li></ol><p>四个都符合三特征：可复制、可参数化、可自动化。这节课我们挑第一个，技术文档自动更新，作为示范动手写。理由很简单： <strong>它解决了老项目最普遍、最让人头疼的问题</strong>。这种 SKILL 的价值，最容易被人直接感受到。</p><h3 id="一个老项目到底需要多少个-skill" tabindex="-1">一个老项目到底需要多少个 SKILL <a class="header-anchor" href="#一个老项目到底需要多少个-skill" aria-label="Permalink to &quot;一个老项目到底需要多少个 SKILL&quot;">​</a></h3><p>挖之前先说克制。你可能一下子兴奋起来，想把上面四个场景全写成 SKILL，再加几个自己想到的。我不建议。 <strong>一个老项目 5-10 个 SKILL 够用了，甚至可能会小于 3 个</strong>。如果一定让我说，我建议控制在 5 个以内（当然需要看你系统的复杂度）。</p><p>太多会出现“一句话匹配多个 SKILL”的情况，AI 判断哪个该触发会迷茫。 <strong>SKILL 数量不代表 AI 协作能力，写得准、用得勤才是</strong>。</p><p>我的节奏建议： <strong>先挖 3 个最高频的流程写成 SKILL，用一个月，觉得真的有用再扩展</strong>。第一个就按这一讲的“技术文档自动更新”写，后面两个留给你自己挖。</p><p>记得，挖的时候回到三特征判断法：你最近一个月在反复做什么，这件事可复制吗？可参数化吗？可自动化吗？三个都满足，就写。</p><p>不要追求“一开始就写一套完美的 SKILL 体系”。 <strong>SKILL 是养出来的，不是设计出来的</strong>。第一版只要能跑，能解决一个具体痛点就够了。</p><h2 id="实操开始-让-ai-帮你挖" tabindex="-1">实操开始：让 AI 帮你挖 <a class="header-anchor" href="#实操开始-让-ai-帮你挖" aria-label="Permalink to &quot;实操开始：让 AI 帮你挖&quot;">​</a></h2><p>理论讲完，开始挖。挖 SKILL 这件事本身不是手动一条条想， <strong>让 AI 帮你扫一遍项目，给你一份候选清单</strong>，然后你来选哪个先做。</p><h3 id="第一步-让-ai-分析项目重复流程" tabindex="-1">第一步：让 AI 分析项目重复流程 <a class="header-anchor" href="#第一步-让-ai-分析项目重复流程" aria-label="Permalink to &quot;第一步：让 AI 分析项目重复流程&quot;">​</a></h3><p>提示词：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扫一下当前项目（包括 git log、CLAUDE.md、docs/、README、CONTRIBUTING、</span></span>
<span class="line"><span>.github/），找出团队反复在做的操作流程。</span></span>
<span class="line"><span>判断标准是三特征：可复制、可参数化、可自动化。三个都满足才算值得做 SKILL 的候选。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>把找到的候选列出来，每个写明：流程名、为什么是反复的、能参数化的部分是什么、</span></span>
<span class="line"><span>起点和终点是什么。最后给我用一个表格总结。</span></span></code></pre></div><p>跑完你会拿到一份清单，可能 5-10 项，这是这个项目里所有候选 SKILL 的集合。运行后 Spring AI Alibaba Admin 这个项目生成了四个点。我第一眼就看到了CRUD脚手架，这也是我们最经常遇到的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/89fba256a05d1b62f7b1356340ac47bc.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/89fba256a05d1b62f7b1356340ac47bc.png" alt=""></a></p><h3 id="第二步-让-ai-出-top-3-推荐" tabindex="-1">第二步：让 AI 出 Top 3 推荐 <a class="header-anchor" href="#第二步-让-ai-出-top-3-推荐" aria-label="Permalink to &quot;第二步：让 AI 出 Top 3 推荐&quot;">​</a></h3><p>提示词：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从上面的清单里挑 3 个最高优先级的，给我做成候选 SKILL。</span></span>
<span class="line"><span>每个候选写：name（英文）、description、预期 steps、allowed-tools。</span></span>
<span class="line"><span>优先级判断标准：频率高、痛点深、自动化收益大。用表格总结，包含类型和理由。</span></span></code></pre></div><p>跑完你会拿到三个候选。我的预期： <strong>Top 3 大概率会包含“技术文档自动更新”这一类</strong>，因为它的频率最高、痛点最深（文档腐烂）、自动化收益最大（一个 SKILL 替代每周几小时人力维护）。你看，第二个就是文档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/09c4379b7b79b4416d3491ccbfc4ddc6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/09c4379b7b79b4416d3491ccbfc4ddc6.png" alt=""></a></p><h3 id="第三步-让-ai-生成完整的-crud-skill" tabindex="-1">第三步： 让 AI 生成完整的 CRUD SKILL <a class="header-anchor" href="#第三步-让-ai-生成完整的-crud-skill" aria-label="Permalink to &quot;第三步： 让 AI 生成完整的 CRUD SKILL&quot;">​</a></h3><p>提示词：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成代码中 CRUD 的 SKILL。</span></span>
<span class="line"><span>注意按照标准格式和放在标准目录。</span></span>
<span class="line"><span>结果放到 .claude/skills/ 目录中。</span></span></code></pre></div><p>这句话的提示词基本就是通用的，你复制就行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/21d0021dbb2b4e5011e47e7c2b76b6d8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/21d0021dbb2b4e5011e47e7c2b76b6d8.png" alt=""></a></p><h3 id="第四步-生成技术文档自动更新的-skill" tabindex="-1">第四步：生成技术文档自动更新的 SKILL <a class="header-anchor" href="#第四步-生成技术文档自动更新的-skill" aria-label="Permalink to &quot;第四步：生成技术文档自动更新的 SKILL&quot;">​</a></h3><p>提示词：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于上面的候选，给我生成完整的 SKILL.md。要求：</span></span>
<span class="line"><span>- 名字 docs-auto-sync</span></span>
<span class="line"><span>- description 写清楚什么场景触发、产出是什么</span></span>
<span class="line"><span>- steps 清晰可执行</span></span>
<span class="line"><span>- allowed-tools 限制到最小</span></span>
<span class="line"><span>- 重要：只汇报不一致的地方，不要自动改文件，让人决定怎么处理</span></span>
<span class="line"><span>保存到 .claude/skills/docs-auto-sync/SKILL.md。</span></span></code></pre></div><p>AI 给你生成的内容大概长这样（这是一个我跑出来的版本，给你做参考）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># docs-auto-sync</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对照代码（Controller、Entity、SQL）与文档（\`docs/api-list.md\`、\`docs/data-model.md\`）做交叉比对，输出不一致清单，**不自动修改任何文件**，由人决定如何处理。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 触发场景</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 新增或修改了 Controller（接口变更、路径变更、参数变更）</span></span>
<span class="line"><span>- 新增或修改了 Entity 类或 SQL 表定义（字段变更、新表、删表）</span></span>
<span class="line"><span>- 怀疑文档与代码已经偏移，想做一次全量对齐检查</span></span>
<span class="line"><span>- PR review 前确认文档是否跟上了代码变更</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 产出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一份结构化差异报告，分两节：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. **接口差异**（代码 vs \`docs/api-list.md\`）：新增接口、删除接口、路径/方法变更、入参/返回类型变更</span></span>
<span class="line"><span>2. **数据模型差异**（Entity/SQL vs \`docs/data-model.md\`）：新增表/实体、删除表/实体、字段增删、类型变更、枚举值变更</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每条差异标注：来源文件 + 行号、当前代码实际值、文档记录值、建议动作（更新文档 / 核实代码 / 忽略）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Usage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span>/docs-auto-sync [targetModule] [docTarget]</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 参数 | 必填 | 默认值 | 说明 |</span></span>
<span class="line"><span>|------|------|--------|------|</span></span>
<span class="line"><span>| \`targetModule\` | 否 | \`all\` | 模块名（如 \`MCP\`、\`AgentSchema\`）或 \`all\` 全量扫描 |</span></span>
<span class="line"><span>| \`docTarget\` | 否 | \`both\` | \`api\`（只查接口）、\`model\`（只查数据模型）、\`both\` |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**示例**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span>/docs-auto-sync                        # 全量扫描，两个文档都对比</span></span>
<span class="line"><span>/docs-auto-sync McpServer api          # 只对比 MCP 模块的接口清单</span></span>
<span class="line"><span>/docs-auto-sync all model              # 全量扫描数据模型</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## allowed-tools</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`Read\`、\`Bash\`（仅用于 \`find\` / \`grep\` 定位文件）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**不使用** \`Write\`、\`Edit\`、\`Agent\`。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Instructions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>When the user runs \`/docs-auto-sync [targetModule] [docTarget]\`:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 0 — 解析参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. \`targetModule\` 默认 \`all\`；\`docTarget\` 默认 \`both\`</span></span>
<span class="line"><span>2. 若 \`targetModule\` 不是 \`all\`，后续所有 find/grep 限定到包含该模块名的文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 1 — 收集代码侧接口清单（当 docTarget 为 \`api\` 或 \`both\`）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用 Bash 扫描所有 Controller 文件：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>find . -name &#39;*Controller.java&#39; -not -path &#39;*/test/*&#39;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每个目标 Controller（\`targetModule=all\` 则全部），提取：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>grep -n &#39;@RequestMapping\\|@GetMapping\\|@PostMapping\\|@PutMapping\\|@DeleteMapping\\|@PatchMapping&#39; &amp;lt;file&gt;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>从代码中记录每个 endpoint 的：</span></span>
<span class="line"><span>- HTTP 方法（GET/POST/PUT/DELETE/PATCH）</span></span>
<span class="line"><span>- 完整路径（\`&amp;#64;RequestMapping\` 前缀 + 方法注解路径拼接）</span></span>
<span class="line"><span>- 方法签名中的入参类型（\`&amp;#64;RequestBody\`、\`&amp;#64;RequestParam\`、\`&amp;#64;PathVariable\`）</span></span>
<span class="line"><span>- 返回类型（\`Result&amp;lt;T&amp;gt;\`、\`Flux&amp;lt;T&amp;gt;\`、\`SseEmitter\` 等）</span></span>
<span class="line"><span>- 所在文件 + 行号</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 2 — 收集代码侧数据模型清单（当 docTarget 为 \`model\` 或 \`both\`）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**2a. 扫描 Entity 类**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span># agentscope 侧（MyBatis-Plus）</span></span>
<span class="line"><span>find . -name &#39;*Entity.java&#39; -not -path &#39;*/test/*&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># admin 侧（JPA）</span></span>
<span class="line"><span>find . -name &#39;*DO.java&#39; -not -path &#39;*/test/*&#39;</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每个目标 Entity 文件，提取：</span></span>
<span class="line"><span>- \`&amp;#64;TableName\` 或 \`&amp;#64;Table(name=...)\` → 表名</span></span>
<span class="line"><span>- 所有字段名（驼峰）+ Java 类型</span></span>
<span class="line"><span>- \`&amp;#64;TableId\` / \`&amp;#64;Id\` 标注的主键字段</span></span>
<span class="line"><span>- \`&amp;#64;TableField(&quot;snake_name&quot;)\` 映射的列名</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**2b. 扫描 SQL 文件**</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>grep -n &#39;CREATE TABLE\\|^\\s*\`\\|^\\s*[a-z]&#39; docker/middleware/init/mysql/admin-schema.sql</span></span>
<span class="line"><span>grep -n &#39;CREATE TABLE\\|^\\s*\`\\|^\\s*[a-z]&#39; docker/middleware/init/mysql/agentscope-schema.sql</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>从 SQL 中记录每张表的：表名、列名、列类型、是否有 NOT NULL / DEFAULT、注释</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 3 — 读取现有文档</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span># 读 docs/api-list.md，按 ## 章节分组</span></span>
<span class="line"><span># 读 docs/data-model.md，按 ### 表名分组</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用 \`Read\` 工具读取两个文档，解析出：</span></span>
<span class="line"><span>- api-list.md：每个模块的接口列表（方法 + 路径 + 入参说明 + 返回说明）</span></span>
<span class="line"><span>- data-model.md：每张表的字段列表（字段名 + 类型 + 说明）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 4 — 交叉比对：接口</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每个从代码提取的 endpoint，在 api-list.md 中查找对应记录：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**匹配规则**：HTTP 方法 + 路径完全相同为同一接口。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每条 endpoint 判断：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 情况 | 标记 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| 代码有，文档无 | \`[新增接口]\` — 文档缺失 |</span></span>
<span class="line"><span>| 文档有，代码无 | \`[已删接口]\` — 文档过期 |</span></span>
<span class="line"><span>| 路径相同但方法不同 | \`[方法变更]\` |</span></span>
<span class="line"><span>| 入参类型与文档描述不符 | \`[入参变更]\` |</span></span>
<span class="line"><span>| 返回类型与文档描述不符 | \`[返回变更]\` |</span></span>
<span class="line"><span>| 完全一致 | 不输出，只统计通过数 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 5 — 交叉比对：数据模型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每张从 Entity/SQL 提取的表，在 data-model.md 中查找对应 \`### {tableName}\` 章节：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 情况 | 标记 |</span></span>
<span class="line"><span>|------|------|</span></span>
<span class="line"><span>| 代码/SQL 有表，文档无章节 | \`[新增表]\` — 文档缺失 |</span></span>
<span class="line"><span>| 文档有章节，代码/SQL 无表 | \`[已删表]\` — 文档过期 |</span></span>
<span class="line"><span>| 表存在，但字段在代码中有、文档无 | \`[新增字段]\` |</span></span>
<span class="line"><span>| 表存在，但字段在文档中有、代码无 | \`[已删字段]\` |</span></span>
<span class="line"><span>| 字段存在，但类型不符 | \`[类型变更]\` |</span></span>
<span class="line"><span>| 字段存在，但枚举值说明不符 | \`[枚举变更]\` |</span></span>
<span class="line"><span>| 完全一致 | 不输出，只统计通过数 |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 6 — 输出差异报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**格式要求**：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span>## docs-auto-sync 差异报告</span></span>
<span class="line"><span>扫描范围：{targetModule} / {docTarget}</span></span>
<span class="line"><span>扫描时间：{当前日期}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 摘要</span></span>
<span class="line"><span>- 接口：{通过数} 条一致，{差异数} 条不一致</span></span>
<span class="line"><span>- 数据模型：{通过数} 条一致，{差异数} 条不一致</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 接口差异（共 N 条）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### [新增接口] POST /console/v1/xxx</span></span>
<span class="line"><span>- 代码位置：\`XxxController.java:42\`</span></span>
<span class="line"><span>- 文档现状：docs/api-list.md 中无此接口</span></span>
<span class="line"><span>- 建议动作：在 docs/api-list.md 对应章节追加该接口说明</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### [已删接口] DELETE /api/prompt/session</span></span>
<span class="line"><span>- 文档位置：\`docs/api-list.md:105\`</span></span>
<span class="line"><span>- 代码现状：未找到对应 Controller 方法</span></span>
<span class="line"><span>- 建议动作：确认是否已废弃，若是则从 api-list.md 中删除</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### [入参变更] GET /console/v1/accounts</span></span>
<span class="line"><span>- 代码位置：\`AccountController.java:67\`</span></span>
<span class="line"><span>- 代码实际：入参 \`AccountQuery &amp;#123; page, size, keyword, type &amp;#125;\`</span></span>
<span class="line"><span>- 文档记录：入参 \`BaseQuery &amp;#123; page, size, keyword &amp;#125;\`</span></span>
<span class="line"><span>- 差异：文档缺少 \`type\` 字段</span></span>
<span class="line"><span>- 建议动作：更新 docs/api-list.md 对应入参说明</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 数据模型差异（共 N 条）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### [新增字段] 表 account — 字段 \`gmt_last_login\`</span></span>
<span class="line"><span>- 代码位置：\`AccountEntity.java:45\` / \`agentscope-schema.sql:28\`</span></span>
<span class="line"><span>- 文档现状：docs/data-model.md ### account 章节无此字段</span></span>
<span class="line"><span>- 建议动作：在 data-model.md account 表中补充该字段</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#### [类型变更] 表 experiment_result — 字段 \`score\`</span></span>
<span class="line"><span>- 代码位置：\`ExperimentResultDO.java:33\`</span></span>
<span class="line"><span>- 代码实际：\`BigDecimal\`（SQL: \`DECIMAL(3,2)\`）</span></span>
<span class="line"><span>- 文档记录：\`Float\`</span></span>
<span class="line"><span>- 建议动作：修正 data-model.md 中 score 字段的类型说明</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 无需处理的已知情况</span></span>
<span class="line"><span></span></span>
<span class="line"><span>以下差异是已知的设计决策，不代表文档错误：</span></span>
<span class="line"><span>- \`ChatSession\`：无 MySQL 表，存 Redis，文档中已有&quot;非 MySQL 实体&quot;节说明</span></span>
<span class="line"><span>- \`DocumentChunk\`：无 MySQL 表，存 Elasticsearch，同上</span></span>
<span class="line"><span>- \`GlobalConfig\`：运行时 DTO，非持久化，同上</span></span>
<span class="line"><span>\`\`\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Step 7 — 结束</span></span>
<span class="line"><span></span></span>
<span class="line"><span>报告输出后：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- **不修改任何文件**</span></span>
<span class="line"><span>- 告知用户：如需逐条修复，可用 \`/add-crud-module\` 补充新模块，或手动 Edit 对应章节</span></span>
<span class="line"><span>- 若差异数为 0，输出&quot;文档与代码完全一致，无需更新&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Notes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 比对时忽略注释风格、空白行、措辞差异，只关注结构性不一致（路径、方法、字段名、类型）</span></span>
<span class="line"><span>- Entity 字段用驼峰，文档字段用 snake_case，比对时统一转换后再匹配</span></span>
<span class="line"><span>- \`targetModule\` 模糊匹配：输入 \`MCP\` 可匹配 \`McpServerController\`、\`mcp_server\` 表</span></span>
<span class="line"><span>- 若同一路径在多个 Controller 中出现（如继承/覆盖），以最终注册到 Spring 的为准，扫描时注意 \`&amp;#64;RequestMapping\` 前缀叠加</span></span>
<span class="line"><span>- \`docs/data-model.md\` 中&quot;非 MySQL 实体&quot;节（ChatSession / DocumentChunk / GlobalConfig）不参与 SQL 比对，跳过</span></span></code></pre></div><h3 id="第五步-测试-skill-真的能被触发" tabindex="-1">第五步：测试 SKILL 真的能被触发 <a class="header-anchor" href="#第五步-测试-skill-真的能被触发" aria-label="Permalink to &quot;第五步：测试 SKILL 真的能被触发&quot;">​</a></h3><p>写完 SKILL 最容易犯的错是放那儿不验证。三个测试动作必做：</p><ul><li><p><strong>测试一</strong>，说一句应该匹配的话：“我刚改完一批 Controller，帮我看看文档还对不对得上”。Claude Code 应该自动加载 <code>docs-auto-sync</code> 并按步骤跑。</p></li><li><p><strong>测试二</strong>，说一句故意不匹配的话：“帮我检查一下这段代码”。这句话和文档同步无关，SKILL 不应该被加载。如果 AI 错误加载了，说明 description 太宽泛。</p></li><li><p><strong>测试三</strong>，真跑一次，看输出符不符合预期。检查：是不是按 5 个步骤走了、是不是列了具体不一致点、有没有自作主张改文件。</p></li></ul><p>三个测试过了，SKILL 才算上线。</p><h2 id="几个注意点" tabindex="-1">几个注意点 <a class="header-anchor" href="#几个注意点" aria-label="Permalink to &quot;几个注意点&quot;">​</a></h2><h3 id="claude-md-和-skill-的分工" tabindex="-1">CLAUDE.md 和 SKILL 的分工 <a class="header-anchor" href="#claude-md-和-skill-的分工" aria-label="Permalink to &quot;CLAUDE.md 和 SKILL 的分工&quot;">​</a></h3><p>到这里第二部分的核心都讲完了。回头看看 10 讲和 11 讲的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/2bcecaf385270144c685c08ec381d581.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/976622/2bcecaf385270144c685c08ec381d581.png" alt=""></a></p><p>两讲对称：10 讲讲“怎么写”（CLAUDE.md 的常识），11 讲讲“怎么挖”（SKILL 的流程）。</p><p><strong>一起看才完整</strong>：CLAUDE.md 告诉 AI 这是什么项目，SKILL 告诉 AI 怎么做特定的事。前者是静态知识，后者是动态能力。</p><h3 id="_60-分起步-养到-90-分" tabindex="-1">60 分起步，养到 90 分 <a class="header-anchor" href="#_60-分起步-养到-90-分" aria-label="Permalink to &quot;60 分起步，养到 90 分&quot;">​</a></h3><p>SKILL 不是一次写完美的。AI 帮你生成的第一版大概只能到 60 分。不要追求第一版就完美，追求“能跑、能解决一个具体痛点”就够了。</p><p>跑完 AI 初版，你手动补 10-20 分到 70-80：调 description 让触发更精准、改 steps 按你团队真实流程走、收紧 allowed-tools 避免越权。这部分调整大概花一两个小时。</p><p>用一个月，在每次实际触发中打磨到 80+：发现误触发就收紧 description、发现漏触发就扩展场景、发现步骤不对就调 steps。这个阶段每次发现问题改一点，半年后 SKILL 才真正成熟。</p><p>持续迭代到 90+：这个 SKILL 就成了团队的标配资产。新人入职装上就能用，老人改造时不用每次想流程。</p><p>SKILL 是养出来的，不是写出来的。</p><h3 id="不要堆工具-要在场景里用工具" tabindex="-1">不要堆工具，要在场景里用工具 <a class="header-anchor" href="#不要堆工具-要在场景里用工具" aria-label="Permalink to &quot;不要堆工具，要在场景里用工具&quot;">​</a></h3><p>这个模块快结束了，我想再强调下这门课的“道”。</p><p>回想 04 讲我给你的那张工具全景图，我说过： <strong>工具箱要全，但你不需要每天深度研究每个工具</strong>。你只要知道地图、知道最好用的几件工具的用法、其他大概有什么、用在哪里。这节课就是这个思想的具体演绎。</p><p>你团队的“文档腐烂”问题，这是场景、是事。你需要“自动同步文档”的方案，这是工具、是 SKILL。你打开工具箱发现 SKILL 这个东西，刚好能用。</p><p><strong>不是因为“我要学 SKILL”才学 SKILL，是因为“我有这个问题”才用 SKILL</strong>。</p><p>整门课从 04 讲铺武器库地图、到 06 讲八步心法、到这一讲挖 SKILL，这条线就是想告诉你： <strong>学 AI 编程不是堆工具的过程，是建立“场景驱动用工具”的思维方式</strong>。</p><p>美团创始人王兴有句经典的话：和高人聊，从书上学，在事上练。一定要在“事上练”，工具是死的，场景是活的，带着场景去用工具，工具才有价值，盯着工具不看场景，学多少都用不上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲核心就一件事： <strong>从老项目里挖出一个重复流程，写成第一个 SKILL</strong>。</p><p>老项目和 SKILL 天然契合：老项目里“反复做但没沉淀”的流程多得挖不完，SKILL 让团队的下限被拉到上限。</p><p>挖的方法：让 AI 扫项目找候选清单、让 AI 出 Top 3 推荐、你选一个让 AI 生成完整 SKILL.md。三步走，比手动想快十倍。</p><p>我们这一讲挑的是“技术文档自动更新”，解决文档腐烂这个老项目通病。这个 SKILL 的价值你一旦用上就回不去了。</p><p>挖完不要贪多。 <strong>5-10 个够用，先挖 3 个用一个月</strong>。</p><p>写完不要追求完美。60 分起步，养到 90 分。SKILL 是养出来的，不是设计出来的。</p><p>到这里第二部分的方法论全部讲完了。docs/ 里有五份资产（架构图、模块图、依赖图、接口清单、数据模型）、项目根目录有一份 CLAUDE.md、 <code>.claude/skills/</code> 里有一个你自己挖出来的 SKILL。这就是老项目的 AI 协作基础设施。</p><p>下一讲是第二部分的实操课，我会把 08-11 这四讲的提示词全部串起来，在 Spring AI Alibaba Admin 上跑一遍完整流程。第三部分就进入编译运行和护栏了。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你手上项目最让你头疼的“反复做但没沉淀”的流程是什么？这件事符合三特征（可复制、可参数化、可自动化）吗？如果让 AI 帮你出 Top 3 候选 SKILL，你猜会包括它吗？</p></li><li><p>你们团队现在有没有“文档腐烂”的问题？docs/ 里的内容多久没更新了？如果一个 SKILL 能自动同步代码和文档，它能给你团队省多少时间？</p></li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,85)])])}const L=n(e,[["render",i]]);export{g as __pageData,L as default};
